// Probe: validate interleaved GMMA smem layouts + descriptors for
//   QK:  S[64,64]  = Q[64,576] * K[64,576]"'^T   (B K-major over kv rows)
//   PV:  O[64,128] = P[64,64]  * V[64,128]     (B MN-major over same tile)
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <torch/extension.h>
#include "wgmma_gen.cuh"

#define DEV __device__ __forceinline__

namespace {

constexpr int kRowDim = 576;   // dims per row
constexpr int kDimCm = kRowDim / 8;  // 72 core-matrix columns

DEV unsigned smem_u32(const void* p) {
  return static_cast<unsigned>(__cvta_generic_to_shared(p));
}

DEV unsigned long long gdesc(unsigned addr, int lbo_units, int sbo_units) {
  return (static_cast<unsigned long long>(addr >> 4) & 0x3FFFu) |
         (static_cast<unsigned long long>(lbo_units & 0x3FFFu) << 16) |
         (static_cast<unsigned long long>(sbo_units & 0x3FFFu) << 32);
}

// Interleaved (SWIZZLE_NONE) layout: core matrix CM(rc, dc) = 8 rows x 8 dims at
// byte offset 128*(rc*kDimCm + dc); element (r,d) -> + (r%8)*16 + (d%8)*2.
DEV int tile_off(int row, int dim) {
  return 128 * ((row / 8) * kDimCm + (dim / 8)) + (row % 8) * 16 + (dim % 8) * 2;
}

__global__ void probe_kernel(const __nv_bfloat16* __restrict__ q,
                             const __nv_bfloat16* __restrict__ k,
                             float* __restrict__ s_out, float* __restrict__ o_out) {
  extern __shared__ __align__(128) unsigned char smem[];
  __nv_bfloat16* sQ = reinterpret_cast<__nv_bfloat16*>(smem);              // 64*576
  __nv_bfloat16* sK = sQ + 64 * kRowDim;                                   // 64*576
  __nv_bfloat16* sP = sK + 64 * kRowDim;                                   // 64*64

  int tid = threadIdx.x;
  for (int i = tid; i < 64 * kRowDim; i += blockDim.x) {
    int r = i / kRowDim, d = i % kRowDim;
    *reinterpret_cast<__nv_bfloat16*>(smem + tile_off(r, d)) = q[i];
    *reinterpret_cast<__nv_bfloat16*>(smem + 64 * kRowDim * 2 + tile_off(r, d)) = k[i];
  }
  // P tile: [64 rows, 64 keys], core matrix CM(hc, kc) at 128*(hc*8+kc)
  for (int i = tid; i < 64 * 64; i += blockDim.x) {
    int r = i / 64, c = i % 64;
    int off = 128 * ((r / 8) * 8 + (c / 8)) + (r % 8) * 16 + (c % 8) * 2;
    *reinterpret_cast<__nv_bfloat16*>(sP + off / 2) =
        __float2bfloat16(0.001f * static_cast<float>((r * 7 + c) % 13));
  }
  __syncthreads();

  float dq[64];
#pragma unroll
  for (int i = 0; i < 64; ++i) dq[i] = 0.f;
  float dp[128];
#pragma unroll
  for (int i = 0; i < 128; ++i) dp[i] = 0.f;

  unsigned qAddr = smem_u32(sQ), kAddr = smem_u32(sK), pAddr = smem_u32(sP);
  // A = Q: K-major, LBO = 8 (dim cm step), SBO = 72*8 = 576 (row cm step)
  unsigned long long qDesc = gdesc(qAddr, 8, 8 * kDimCm);
  // B = K tile read as [k=dim][n=row]: same layout -> LBO = 8, SBO = 576
  unsigned long long kDesc = gdesc(kAddr, 8, 8 * kDimCm);
  unsigned long long pDesc = gdesc(pAddr, 8, 8 * 8);
  // B = V: MN-major over the K tile: LBO = 576 (row cm step), SBO = 8 (dim cm step)
  unsigned long long vDesc = gdesc(kAddr, 8 * kDimCm, 8);

  wgmma_fence();
#pragma unroll
  for (int ks = 0; ks < kRowDim / 16; ++ks) {
    wgmma_m64n64k16_ss<0, 0>(dq, qDesc + ks * 16, kDesc + ks * 16, ks ? 1 : 0);
  }
  wgmma_commit();
  wgmma_wait<0>();

  for (int i = tid; i < 64 * 64; i += blockDim.x) {
    int m = i / 64, n = i % 64;
    // C layout m64n64: thread t=(a,b,c): rows b+16c, b+16c+8; cols 2a+d+8f
    int a = (tid % 32) % 4, b = (tid % 32) / 4, c = tid / 32;
    (void)a; (void)b; (void)c;
    s_out[i] = dq[(m % 16) < 8 ? 0 : 0];  // placeholder, replaced below
  }
  // write S properly using the layout mapping
  {
    int a = (tid % 32) % 4, b = (tid % 32) / 4, c = tid / 32;
    for (int f = 0; f < 8; ++f) {
      for (int e = 0; e < 2; ++e) {
        for (int dd = 0; dd < 2; ++dd) {
          int m = b + 16 * c + 8 * e;
          int n = 2 * a + dd + 8 * f;
          s_out[m * 64 + n] = dq[4 * f + 2 * e + dd];
        }
      }
    }
  }
  __syncthreads();

  // PV: O[64,128] = P[64,64] * V[64,128] ; k = 64 keys -> 4 k-steps
#pragma unroll
  for (int ks = 0; ks < 4; ++ks) {
    // A advance per k16 = 2 key-chunks = 256B = 16 units;  B advance = 2 row-chunks = 18432B = 1152 units
    wgmma_m64n128k16_ss<0, 1>(dp, pDesc + ks * 16, vDesc + ks * 1152, ks ? 1 : 0);
  }
  wgmma_commit();
  wgmma_wait<0>();
  {
    int a = (tid % 32) % 4, b = (tid % 32) / 4, c = tid / 32;
    for (int f = 0; f < 16; ++f) {
      for (int e = 0; e < 2; ++e) {
        for (int dd = 0; dd < 2; ++dd) {
          int m = b + 16 * c + 8 * e;
          int n = 2 * a + dd + 8 * f;
          o_out[m * 128 + n] = dp[4 * f + 2 * e + dd];
        }
      }
    }
  }
}

}  // namespace

void probe_launch(torch::Tensor q, torch::Tensor k, torch::Tensor s_out, torch::Tensor o_out) {
  int smem = (64 * kRowDim * 2 + 64 * 64) * 2;
  cudaFuncSetAttribute(probe_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
  probe_kernel<<<1, 128, smem>>>(reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
                                 reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
                                 s_out.data_ptr<float>(), o_out.data_ptr<float>());
  cudaError_t e = cudaDeviceSynchronize();
  TORCH_CHECK(e == cudaSuccess, "probe failed: ", cudaGetErrorString(e));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("probe", &probe_launch); }
