        s[4 * f + d] = valid[f][d] ? s[4 * f + d] : kNegBig;
        s[4 * f + 2 + d] = valid[f][d] ? s[4 * f + 2 + d] : kNegBig;
        mx0 = fmaxf(mx0, s[4 * f + d]);
        mx1 = fmaxf(mx1, s[4 * f + 2 + d]);
      }
    }
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 1));
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 2));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 1));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 2));
    if (a4 == 0) {
      sStat[wg * kHeadsPerCta + b8 + 16 * c4] = mx0;
      sStat[wg * kHeadsPerCta + b8 + 16 * c4 + 8] = mx1;
    }
    __syncthreads();  // both warpgroup maxima are visible

    const int row0 = b8 + 16 * c4;
    const int row1 = row0 + 8;
    const float cmax0 = fmaxf(sStat[row0], sStat[kHeadsPerCta + row0]);
    const float cmax1 = fmaxf(sStat[row1], sStat[kHeadsPerCta + row1]);

    // ---- online softmax update: rescale accumulators, then rebuild P
    const float mNew0 = fmaxf(mRun0, cmax0);
    const float mNew1 = fmaxf(mRun1, cmax1);
    const float fac0 = expf(mRun0 - mNew0);
    const float fac1 = expf(mRun1 - mNew1);
    mRun0 = mNew0;
    mRun1 = mNew1;
    if (fac0 "'!= 1.f) {
#pragma unroll
      for (int i = 0; i < kOregs; i += 2) o[i] *= fac0;
    }
    if (fac1 != 1.f) {
#pragma unroll
      for (int i = 1; i < kOregs; i += 2) o[i] *= fac1;
    }
    lRun0 *= fac0;
    lRun1 *= fac1;

    float sum0 = 0.f, sum1 = 0.f;
#pragma unroll
    for (int e = 0; e < 2; ++e) {
      const float mm = e ? mNew1 : mNew0;
      unsigned char* pd = sP + 128 * ((2 * c4 + e) * (kChunkKeys / 8) + 4 * wg) + b8 * 16 + 4 * a4;
#pragma unroll
      for (int f = 0; f < 4; ++f) {
        const float p0 = valid[f][0] ? expf(s[4 * f + 2 * e] - mm) : 0.f;
        const float p1 = valid[f][1] ? expf(s[4 * f + 2 * e + 1] - mm) : 0.f;
        *reinterpret_cast<__nv_bfloat162*>(pd + 128 * f) = __floats2bfloat162_rn(p0, p1);
        if (e == 0) {
          sum0 += p0 + p1;
        } else {
          sum1 += p0 + p1;
        }
      }
    }
    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 1);
    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 2);
    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 1);
    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 2);
    lRun0 += sum0;
    lRun1 += sum1;
    __syncthreads();  // P tile complete

    // ---- PV: O[64, 256] += P[64, 64] * V[64, 256]
    wgmma_fence();
    {
      const unsigned long long vDesc =
          gdesc(tile + 128 * (32 * wg * (kDimCm / 8)), 8 * kDimCm, 8);
#pragma unroll
      for (int ks = 0; ks < kChunkKeys / 16; ++ks) {
        wgmma_m64n128k16_ss<0, 1>(*reinterpret_cast<float(*)[64]>(&o[64 * ks]),
                                  pDesc + ks * 16, vDesc + ks * (2 * 8 * kDimCm), ks ? 1 : 0);
      }
      wgmma_commit();
    }
  }
  wgmma_wait<0>();

  // ---- epilogue: final max/sum across warpgroups, normalize, store
  if (a4 == 0) {
    sStat[wg * kHeadsPerCta + b8 + 16 * c4] = mRun0;
    sStat[wg * kHeadsPerCta + b8 + 16 * c4 + 8] = mRun1;
    sStat[2 * kHeadsPerCta + wg * kHeadsPerCta + b8 + 16 * c4] = lRun0;
    sStat[2 * kHeadsPerCta + wg * kHeadsPerCta + b8 + 16 * c4 + 8] = lRun1;
  }
  __syncthreads();

  const int rowA = b8 + 16 * c4;
  const int rowB = rowA + 8;
  const float mFin0 = fmaxf(sStat[rowA], sStat[kHeadsPerCta + rowA]);
  const float mFin1 = fmaxf(sStat[rowB], sStat[kHeadsPerCta + rowB]);
  const float lFin0 = sStat[2 * kHeadsPerCta + rowA] + sStat[3 * kHeadsPerCta + rowA];
  const float lFin1 = sStat[2 * kHeadsPerCta + rowB] + sStat[3 * kHeadsPerCta + rowB];
  // Both warpgroups accumulated P with reference mRun; the per-warpgroup running
  // max is identical, so the sums are already on the same scale.
  const float inv0 = 1.f / lFin0;
  const float inv1 = 1.f / lFin1;

  __nv_bfloat16* outRow = out + static_cast<size_t>(token * kHeads + headBase) * kDimV +
                          wg * kVdimsWg;
#pragma unroll
  for (int f = 0; f < 32; ++f) {
#pragma unroll
    for (int e = 0; e < 2; ++e) {
      const float inv = e ? inv1 : inv0;
      const int m = b8 + 16 * c4 + 8 * e;
      const int n = 2 * a4 + 8 * f;
      __nv_bfloat162 v =
          __floats2bfloat162_rn(o[4 * f + 2 * e] * inv, o[4 * f + 2 * e + 1] * inv);
      *reinterpret_cast<__nv_bfloat162*>(outRow + static_cast<size_t>(m) * kDimV + n) = v;
    }
  }
  if (a4 == 0) {
    maxLogits[static_cast<size_t>(token) * kHeads + headBase + rowA] = mFin0;
    maxLogits[static_cast<size_t>(token) * kHeads + headBase + rowB] = mFin1;
    lse[static_cast<size_t>(token) * kHeads + headBase + rowA] = mFin0 + __logf(lFin0);
    lse[static_cast<size_t>(token) * kHeads + headBase + rowB] = mFin1 + __logf(lFin1);
  }
}

