// (token, head) with one warp doing the whole reduction). Only used when the
// bundle is compiled for a target without wgmma; the sm_90a build never runs it.
__global__ void sparseAttnFallback(const __nv_bfloat16* __restrict__ q,
                                   const __nv_bfloat16* __restrict__ kv,
                                   const int* __restrict__ indices,
                                   __nv_bfloat16* __restrict__ out,
